import {
  useState,
  useEffect
} from "react";

import axios from "axios";

import ReactMarkdown from "react-markdown";

import { Prism as SyntaxHighlighter }
from "react-syntax-highlighter";

import { oneDark }
from "react-syntax-highlighter/dist/esm/styles/prism";

function App() {

  /* =========================
     LOCAL STORAGE LOAD
  ========================= */

  const [conversations, setConversations] = useState(() => {

    const saved =
      localStorage.getItem("conversations");

    return saved
      ? JSON.parse(saved)
      : [];
  });

  const [currentChatId, setCurrentChatId] =
    useState(() => {

      const saved =
        localStorage.getItem("currentChatId");

      return saved
        ? Number(saved)
        : null;
    });

    useEffect(() => {

  const loadVoices = () => {

    const availableVoices =
      speechSynthesis.getVoices();

    setVoices(availableVoices);

    if (availableVoices.length > 0) {

      setSelectedVoice(
        availableVoices[0].name
      );
    }
  };

  loadVoices();

  speechSynthesis.onvoiceschanged =
    loadVoices;

}, []);

  const [message, setMessage] = useState("");

  const [loading, setLoading] = useState(false);

  const [listening, setListening] = useState(false);

const [selectedVoice, setSelectedVoice] =
  useState("");

const [voices, setVoices] = useState([]);





  /* =========================
     SAVE TO LOCAL STORAGE
  ========================= */

  const saveConversations = (
    updatedChats
  ) => {

    setConversations(updatedChats);

    localStorage.setItem(
      "conversations",
      JSON.stringify(updatedChats)
    );
  };

  const saveCurrentChatId = (id) => {

    setCurrentChatId(id);

    localStorage.setItem(
      "currentChatId",
      id
    );
  };

  /* =========================
     CREATE NEW CHAT
  ========================= */

  const createNewChat = () => {

    const newChat = {
      id: Date.now(),
      title: "New Chat",
      messages: []
    };

    const updatedChats = [
      newChat,
      ...conversations
    ];

    saveConversations(updatedChats);

    saveCurrentChatId(newChat.id);
  };

  /* =========================
     CURRENT CHAT
  ========================= */

  const currentChat =
    conversations.find(
      (chat) =>
        chat.id === currentChatId
    );

  /* =========================
     SEND MESSAGE
  ========================= */

  const sendMessage = async () => {

    if (!message.trim()) return;

    let activeChatId =
      currentChatId;

    let updatedChats =
      [...conversations];

    /* CREATE CHAT IF NONE */

    if (!activeChatId) {

      const newChat = {
        id: Date.now(),
        title: message,
        messages: []
      };

      updatedChats = [
        newChat,
        ...updatedChats
      ];

      activeChatId = newChat.id;

      saveCurrentChatId(
        activeChatId
      );
    }

    /* USER MESSAGE */

    const userMessage = {
      role: "user",
      text: message
    };

    updatedChats =
      updatedChats.map((chat) => {

        if (
          chat.id === activeChatId
        ) {

          return {
            ...chat,

            title:
              chat.messages.length === 0
                ? message
                : chat.title,

            messages: [
              ...chat.messages,
              userMessage
            ]
          };
        }

        return chat;
      });

    saveConversations(updatedChats);

    const currentMessage = message;

    setMessage("");

    setLoading(true);

    try {

      /* =========================
         ADD EMPTY AI MESSAGE
      ========================= */

      const emptyAiMessage = {
        role: "ai",
        text: ""
      };

      updatedChats =
        updatedChats.map((chat) => {

          if (
            chat.id === activeChatId
          ) {

            return {
              ...chat,
              messages: [
                ...chat.messages,
                emptyAiMessage
              ]
            };
          }

          return chat;
        });

      saveConversations(updatedChats);

      /* =========================
         STREAMING FETCH
      ========================= */

      const response = await fetch(
        "http://127.0.0.1:8000/api/chat",
        {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json"
          },

          body: JSON.stringify({

            message: currentMessage,

            history:
              updatedChats.find(
                (c) =>
                  c.id === activeChatId
              )?.messages || []
          })
        }
      );

      const reader =
        response.body.getReader();

      const decoder =
        new TextDecoder();

      let aiText = "";

      while (true) {

        const {
          done,
          value
        } = await reader.read();

        if (done) break;

        const chunk =
          decoder.decode(value);

        aiText += chunk;

        updatedChats =
          updatedChats.map((chat) => {

            if (
              chat.id === activeChatId
            ) {

              const updatedMessages =
                [...chat.messages];

              updatedMessages[
                updatedMessages.length - 1
              ] = {

                role: "ai",

                text: aiText
              };

              return {
                ...chat,
                messages:
                  updatedMessages
              };
            }

            return chat;
          });

        saveConversations(
          updatedChats
        );
      }

    } catch (error) {

      console.log(error);

      updatedChats =
        updatedChats.map((chat) => {

          if (
            chat.id === activeChatId
          ) {

            return {
              ...chat,

              messages: [
                ...chat.messages,

                {
                  role: "ai",

                  text:
                    "Backend connection error"
                }
              ]
            };
          }

          return chat;
        });

      saveConversations(updatedChats);
    }

    setLoading(false);
  };

  /* =========================
     DELETE CHAT
  ========================= */

  const deleteChat = (id) => {

    const filteredChats =
      conversations.filter(
        (chat) =>
          chat.id !== id
      );

    saveConversations(
      filteredChats
    );

    if (
      filteredChats.length > 0
    ) {

      saveCurrentChatId(
        filteredChats[0].id
      );

    } else {

      saveCurrentChatId(null);
    }
  };

  /* =========================
     PDF UPLOAD
  ========================= */

  const uploadPDF = async (e) => {

    const file =
      e.target.files[0];

    if (!file) return;

    const formData =
      new FormData();

    formData.append(
      "file",
      file
    );

    try {

      setLoading(true);

      const res = await axios.post(
        "http://127.0.0.1:8000/api/upload-pdf",

        formData,

        {
          headers: {
            "Content-Type":
              "multipart/form-data"
          }
        }
      );

      const aiMessage = {

        role: "ai",

        text:
          res.data.response
      };

      const updatedChats =
        conversations.map((chat) => {

          if (
            chat.id === currentChatId
          ) {

            return {

              ...chat,

              messages: [
                ...chat.messages,
                aiMessage
              ]
            };
          }

          return chat;
        });

      saveConversations(
        updatedChats
      );

    } catch (error) {

      console.log(error);
    }

    setLoading(false);
  };

  /* =========================
     UI
  ========================= */

  return (

    <div className="flex h-screen bg-slate-950 text-white overflow-hidden">

      {/* =========================
         SIDEBAR
      ========================= */}

      <div className="w-72 bg-slate-900 border-r border-slate-800 p-5 flex flex-col">

        <h1 className="text-2xl font-bold text-cyan-400 mb-8">

          AI College Companion

        </h1>

        <button
          onClick={createNewChat}
          className="w-full bg-cyan-500 hover:bg-cyan-600 p-3 rounded-xl font-semibold transition"
        >

          + New Chat

        </button>

        {/* CHAT HISTORY */}

        <div className="mt-8 overflow-y-auto space-y-3 flex-1">

          {
            conversations.map((chat) => (

              <div
                key={chat.id}

                className={`p-3 rounded-xl flex items-center justify-between cursor-pointer transition ${
                  currentChatId === chat.id
                    ? "bg-cyan-500"
                    : "bg-slate-800 hover:bg-slate-700"
                }`}
              >

                <div
                  className="truncate flex-1"

                  onClick={() =>
                    saveCurrentChatId(chat.id)
                  }
                >

                  {chat.title}

                </div>

                <button
                  onClick={() =>
                    deleteChat(chat.id)
                  }

                  className="ml-2 text-red-300 hover:text-red-500"
                >

                  ✕

                </button>

              </div>

            ))
          }

        </div>

      </div>

      {/* =========================
         MAIN CHAT AREA
      ========================= */}

      <div className="flex-1 flex flex-col">

        {/* HEADER */}

        <div className="p-5 border-b border-slate-800 text-2xl font-semibold text-cyan-300 backdrop-blur">

          AI Assistant

        </div>

        {/* =========================
           CHAT MESSAGES
        ========================= */}

        <div className="flex-1 overflow-y-auto p-6 space-y-6">

          {
            currentChat?.messages.map(
              (chat, index) => (

                <div
                  key={index}

                  className={`max-w-4xl p-5 rounded-2xl whitespace-pre-wrap leading-8 shadow-lg ${
                    chat.role === "user"

                      ? "bg-cyan-500 ml-auto text-white"

                      : "bg-slate-800 text-gray-200"
                  }`}
                >

                  {
                    chat.role === "ai"

                      ? (

                        <ReactMarkdown

                          components={{

                            code({

                              inline,

                              className,

                              children,

                              ...props

                            }) {

                              const match =
                                /language-(\w+)/.exec(
                                  className || ""
                                );

                              return !inline &&
                                match ? (

                                <SyntaxHighlighter
                                  style={oneDark}

                                  language={
                                    match[1]
                                  }

                                  PreTag="div"

                                  {...props}
                                >

                                  {String(
                                    children
                                  ).replace(
                                    /\n$/,
                                    ""
                                  )}

                                </SyntaxHighlighter>

                              ) : (

                                <code
                                  className="bg-slate-700 px-1 py-0.5 rounded"

                                  {...props}
                                >

                                  {children}

                                </code>
                              );
                            }
                          }}
                        >

                          {chat.text}

                        </ReactMarkdown>

                      ) : (

                        chat.text
                      )
                  }

                </div>

              ))
          }

          {/* TYPING ANIMATION */}

          {
            loading && (

              <div className="bg-slate-800 p-4 rounded-2xl w-fit flex gap-2">

                <div className="w-2 h-2 bg-white rounded-full animate-bounce"></div>

                <div className="w-2 h-2 bg-white rounded-full animate-bounce delay-100"></div>

                <div className="w-2 h-2 bg-white rounded-full animate-bounce delay-200"></div>

              </div>

            )
          }

        </div>

        {/* =========================
           INPUT AREA
        ========================= */}

        <div className="p-5 border-t border-slate-800 flex gap-4 items-center bg-slate-950">

          <input
            type="text"

            placeholder="Ask anything..."

            value={message}

            onChange={(e) =>
              setMessage(e.target.value)
            }

            onKeyDown={(e) => {

              if (e.key === "Enter") {
                const speakText = (text) => {

  const utterance =
    new SpeechSynthesisUtterance(text);

  const voice = voices.find(
    (v) => v.name === selectedVoice
  );

  if (voice) {

    utterance.voice = voice;
  }

  // EMOTION SETTINGS

  utterance.rate = 1;

  utterance.pitch = 1.2;

  utterance.volume = 1;

  speechSynthesis.speak(utterance);
};
                sendMessage();
              }
            }}

            className="flex-1 p-4 rounded-xl bg-slate-800 border border-slate-700 focus:outline-none focus:ring-2 focus:ring-cyan-500"
          />

          <button
            onClick={sendMessage}

            className="bg-cyan-500 hover:bg-cyan-600 px-6 py-4 rounded-xl font-semibold transition"
          >

            Send

          </button>

          {/* PDF BUTTON */}

          <label className="bg-purple-500 hover:bg-purple-600 px-5 py-4 rounded-xl cursor-pointer font-semibold transition">

            Upload PDF

            <input
              type="file"

              accept=".pdf"

              hidden

              onChange={uploadPDF}
            />

          </label>

        </div>

      </div>

    </div>
  );
}

export default App;
